// in O=C=N-R format (the canonical form Qwen3.5-9B produces), so the check
// fired at the FIRST complete-parse point — which was O=C=NC1 with ring label 1
// unclosed (7 tokens >= minSpanLength=5). The output O=C=NC1>> is RDKit-invalid.
//
// Fix (restoring attempt 9 behavior):
// 1. Use ONLY "N=C=O" for isocyanate detection (not "O=C=N"). For canonical
//    O=C=N-R format SMILES, "N=C=O" never appears as a substring, so the
//    early-close check is always 0; CloseSpanWithinBudget handles closure.
//    For reverse R-N=C=O format, "N=C=O" IS present and early close fires
//    correctly.
// 2. Add ring-balance guard: require each ring-closure digit (1-4) to appear
//    an even number of times in the rendered SMILES before closing. This
//    prevents closing O=C=NC1 (ring-1 count = 1, odd → unbalanced → no close).
//
// Diversity improvement over attempt 9 (20% acc → target 36%):
// Raise temperature from 1.6 to 1.8 in all temperature-controlled phases.
// Keep guidance identical to attempt 9 (the only version with 100% syntax).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   OpenConstrainedSpan: sets currentConstrainedOut := [], insideConstrainedOut := true.
//   parser.IsValidPrefix([]) holds by method precondition. ✓
//
//   complete+NCO+balanced branch: CloseConstrainedSpan sets insideConstrainedOut := false,
//   making the implication vacuously true; currentConstrainedOut := []. ✓
//
//   complete+notNCO or !ringsBalanced branch: SafeTemperatureConstrainedStep hard-masks
//   to parser-valid tokens plus EOS. AppendConstrainedToken postcondition preserves
//   parser.IsValidPrefix on new currentConstrainedOut. EOS → break without mutation. ✓
//
//   incomplete branch (phase 1/2/3): SafePenalizedConstrainedStep,
//   SafeTemperatureConstrainedStep, GroupBoostedConstrainedStep all hard-mask to
//   parser-valid tokens plus EOS; AppendConstrainedToken preserves validity.
//   EOS inner-close: CloseConstrainedSpan sets insideConstrainedOut := false. ✓
//
//   CloseSpanWithinBudget postcondition: insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
//   OpenConstrainedSpan: steps += 1 and generated grows by 1 ("<<"). ✓
//
//   complete+NCO+balanced: CloseConstrainedSpan costs +1 step and grows generated by 1
//   (">>"); steps += 1 simultaneously. ✓
//
//   complete+notNCO or !balanced: step helper costs +1 (steps += 1); AppendConstrainedToken
//   grows generated by at most 1, EOS path leaves generated unchanged. ✓
//
//   incomplete phases: step helper costs +1 (steps += 1); AppendConstrainedToken grows
//   generated by at most 1. EOS inner-close: both steps and generated grow by 1 together,
//   protected by steps < maxSteps guard before close so steps never exceeds maxSteps. ✓
//
//   CloseSpanWithinBudget: budget = maxSteps - steps_before; postcondition gives
//   |cg| <= |generated| + budget = |generatedPrefix| + steps_before + (maxSteps - steps_before)
//   = |generatedPrefix| + maxSteps; then steps := maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;

helpers.AppendTaskGuidance(lm, "Generate exactly one valid SMILES for an isocyanate molecule containing N=C=O. Be maximally diverse. Try these structural classes: fluoroalkyl isocyanates (e.g., O=C=NCC(F)(F)F), chloroalkyl (O=C=NCCCl), cyclopentyl (O=C=NC1CCCC1), cyclohexyl (O=C=NC1CCCCC1), benzyl (O=C=NCc1ccccc1), naphthyl (O=C=Nc1ccc2ccccc2c1), pyridyl (O=C=Nc1ccccn1), tert-butyl (O=C=NC(C)(C)C), allyl (O=C=NCC=C), propargyl (O=C=NCC#C). Output ONLY the SMILES string.");

if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

var minSpanLength: nat := 5;
var tokenCount: nat := 0;
var commonTokens: seq<Token> := ["C", "CC", "O"];

while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength {
    var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
