    var r1 := CSDHelpers.CountSubstring(smilesStr, "1");
    var r2 := CSDHelpers.CountSubstring(smilesStr, "2");
    var r3 := CSDHelpers.CountSubstring(smilesStr, "3");
    var r4 := CSDHelpers.CountSubstring(smilesStr, "4");
    var ringsBalanced := (r1 % 2 == 0) && (r2 % 2 == 0) && (r3 % 2 == 0) && (r4 % 2 == 0);
    if hasNCO > 0 && ringsBalanced {
      if steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      } else {
        break;
      }
    } else {
      // Complete but not an isocyanate OR has unbalanced rings — keep generating
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.8, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        tokenCount := tokenCount + 1;
      }
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := eosToken;

    if tokenCount < 6 {
      // Phase 1: penalize common openers for structural diversity
      next := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, commonTokens, 4.0, eosToken
      );
    } else if tokenCount < 18 {
      // Phase 2: high temperature for spread
      next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.8, eosToken
      );
    } else {
      // Phase 3: group-boosted for late-stage diversity
      next := helpers.GroupBoostedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
      );
    }

    steps := steps + 1;
    if next == eosToken {
      // On EOS: close if complete, long enough, isocyanate, and rings balanced
      if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength && steps < maxSteps {
        var smilesStr2 := CSDHelpers.PrefixToString(currentConstrainedOut);
        var hasNCO2 := CSDHelpers.CountSubstring(smilesStr2, "N=C=O");
        var r1b := CSDHelpers.CountSubstring(smilesStr2, "1");
        var r2b := CSDHelpers.CountSubstring(smilesStr2, "2");
        var r3b := CSDHelpers.CountSubstring(smilesStr2, "3");
        var r4b := CSDHelpers.CountSubstring(smilesStr2, "4");
        var ringsBalanced2 := (r1b % 2 == 0) && (r2b % 2 == 0) && (r3b % 2 == 0) && (r4b % 2 == 0);
        if hasNCO2 > 0 && ringsBalanced2 {
          var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        }
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
      tokenCount := tokenCount + 1;
    }
  }
}

// Fallback: if still inside span with budget remaining, close it now
if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

